def zip_equal(*iterables):
    """``zip`` the input *iterables* together, but raise ``UnequalIterablesError``
    if they have different lengths.

        >>> list(zip_equal([1, 2, 3], ['a', 'b', 'c']))
        [(1, 'a'), (2, 'b'), (3, 'c')]

    This is like ``zip``, except it will raise an error if the iterables
    have different lengths.

        >>> list(zip_equal([1, 2, 3], ['a', 'b']))
        Traceback (most recent call last):
        ...
        more_itertools.more.UnequalIterablesError: zip_equal() argument 2 is shorter than argument 1

    """
    from itertools import zip_longest

    sentinel = object()
    for combo in zip_longest(*iterables, fillvalue=sentinel):
        if sentinel in combo:
            # Find the first exhausted iterator (smallest index with sentinel)
            shorter_idx = None
            longer_idx = None
            for i, item in enumerate(combo):
                if item is sentinel:
                    if shorter_idx is None:
                        shorter_idx = i
                else:
                    if longer_idx is None:
                        longer_idx = i

            if shorter_idx is not None and longer_idx is not None:
                raise UnequalIterablesError(
                    f"zip_equal() argument {shorter_idx + 1} is shorter than argument {longer_idx + 1}"
                )
            elif shorter_idx is not None:
                # All are exhausted - shouldn't happen since we'd return earlier
                raise UnequalIterablesError(
                    f"zip_equal() argument {shorter_idx + 1} is shorter than argument 1"
                )
            return
        yield combo
